param([int]$Year=2007,[int]$Month=1,[string]$RunId='ccn\run_200701_month_002')
$ErrorActionPreference='Stop'; if($RunId -notmatch '^ccn[\\/]run_[A-Za-z0-9_-]+$'){if($RunId -match '^[A-Za-z0-9_-]+$'){$RunId="ccn\$RunId"}else{throw 'RunId must be ccn\run_<id> (or a bare run_<id>, which is placed under ccn).'}}; $RunId=$RunId -replace '/','\'; $project='F:\AER_SHARED_PIPELINE'; $run=Join-Path $project "runs\$RunId"; $log=Join-Path $run 'logs\ccn'; New-Item -ItemType Directory -Force -Path $log,(Join-Path $run 'staging\ccn'),(Join-Path $run 'plots\ccn')|Out-Null
$start=Get-Date -Year $Year -Month $Month -Day 1; $end=$start.AddMonths(1); $inv=[System.Collections.Generic.List[object]]::new()
for($d=$start;$d -lt $end;$d=$d.AddDays(1)){ $date=$d.ToString('yyyy-MM-dd'); $ymd=$d.ToString('yyyyMMdd'); $success="$project\products\ccn\ccn_grid\ccn__ap-final-v1__era5-real__grid5deg__ccn-v1\$Year\$($d.ToString('MM'))\$($d.ToString('dd'))\_SUCCESS"; if(Test-Path $success){$inv.Add([pscustomobject]@{Date=$date;Status='complete_existing'});continue}; $tall="$project\products\tall\t_all\tall__ap-final-v1__era5-real__adapter-v1__qc-v1\$Year\$($d.ToString('MM'))\$($d.ToString('dd'))\T_all_$ymd.mat"; if(-not(Test-Path $tall)){$inv.Add([pscustomobject]@{Date=$date;Status='missing_t_all'});continue}; $env:CCN_BATCH_DATE=$date;$env:CCN_RUN_ROOT=$run; $mlog=Join-Path $log "day_${ymd}.log"; $p=Start-Process matlab.exe -ArgumentList @('-batch',"run('$project\code\batch\run_ccn_day_batch.m')") -RedirectStandardOutput $mlog -Wait -PassThru -WindowStyle Hidden; Remove-Item Env:CCN_BATCH_DATE,Env:CCN_RUN_ROOT -ErrorAction SilentlyContinue; $inv.Add([pscustomobject]@{Date=$date;Status=if($p.ExitCode -eq 0){'complete'}else{'failed'};ExitCode=$p.ExitCode}); if($p.ExitCode -ne 0){break} }
$inv|Export-Csv (Join-Path $run 'date_inventory_ccn.csv') -NoTypeInformation -Encoding UTF8; if(@($inv|? Status -eq 'failed').Count){exit 1}
